/**
 * The browser run's view of the XSS corpus (plan #198 Part 3b §3, §4.1): one `E2eCase` per corpus
 * case, generated by `scripts/gen-xss-e2e-cases.ts` into `fixtures/xss-e2e-cases.json` and
 * committed. `digest` binds a case to its input, so an id cannot keep its entry when its source,
 * variables or entity change; `skip` names why a case cannot run on a real board; `images` are the
 * request paths the case's `<img>` elements load (independent of the renderer).
 *
 * This module has no imports from the client: the generator loads it in Node.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { CorpusCase } from '../src/security/sanitise/xssCorpus.ts';

export type SkipReason = 'entity' | 'varNotUrlSafe' | 'nul';

export interface E2eCase {
  id: string;
  digest: string;
  skip: SkipReason | null;
  images: readonly string[];
}

export const E2E_CASES_FILE = fileURLToPath(
  new URL('./fixtures/xss-e2e-cases.json', import.meta.url),
);

/** SHA-256 hex of JSON.stringify([src, vars, entity]) (well-formed JSON.stringify keeps lone surrogates escaped). */
export function caseDigest(c: CorpusCase): string {
  return createHash('sha256')
    .update(JSON.stringify([c.src, c.vars, c.entity]))
    .digest('hex');
}

const same = (a: readonly string[], b: readonly string[]): boolean =>
  a.length === b.length && a.every((x, i) => x === b[i]);

/** The differences, one line per id (in the generated order, then ids only committed). */
export function compareCases(
  generated: readonly E2eCase[],
  committed: readonly E2eCase[],
): string[] {
  const byId = new Map(committed.map((c) => [c.id, c]));
  const out: string[] = [];
  for (const g of generated) {
    const c = byId.get(g.id);
    if (c === undefined) {
      out.push(`${g.id}: not committed`);
      continue;
    }
    byId.delete(g.id);
    const fields: string[] = [];
    if (g.digest !== c.digest) fields.push('digest');
    if (g.skip !== c.skip) fields.push('skip');
    if (!same(g.images, c.images)) fields.push('images');
    if (fields.length > 0) out.push(`${g.id}: ${fields.join(', ')}`);
  }
  for (const id of byId.keys()) out.push(`${id}: not generated`);
  return out;
}

export function readCommittedCases(file: string = E2E_CASES_FILE): E2eCase[] {
  return (JSON.parse(readFileSync(file, 'utf8')) as { cases: E2eCase[] }).cases;
}
